package com.zidio.keystone.domain;
import jakarta.persistence.*; import lombok.*; import java.time.*;
@Entity @Table(name="work_orders") @Getter @Setter @NoArgsConstructor public class WorkOrder { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true) String code; @Column(nullable=false) String title; @Column(length=4000) String description; @Enumerated(EnumType.STRING) @Column(nullable=false) Priority priority; @Enumerated(EnumType.STRING) @Column(nullable=false) WorkOrderStatus status; @Column(nullable=false) Instant slaDueAt; Instant createdAt; Instant updatedAt; @ManyToOne(fetch=FetchType.EAGER,optional=false) Customer customer; @ManyToOne(fetch=FetchType.EAGER,optional=false) Site site; @ManyToOne(fetch=FetchType.EAGER) AppUser assignee; }
